using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class Payload
{
    public double lo { get; set; }
    public double hi { get; set; }
    public double mid { get; set; }
    public long count { get; set; }
    public int step { get; set; }
}

public static class Core
{
    public const ulong M = 16777216UL;
    public const long K = 5000000L;
    public const ulong MOD = 2147483647UL;
    public const double MODD = 2147483647.0;

    public static long CountShard(int workerIndex, int totalWorkers, double mid, CancellationToken ct)
    {
        long c = 0;
        ulong stride = (ulong)totalWorkers;
        for (ulong i = (ulong)(workerIndex + 1); i <= M; i += stride)
        {
            ulong z = i * 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            z = z ^ (z >> 31);
            double v = (double)(z % MOD) / MODD;
            if (v <= mid) c++;
        }
        return c;
    }
}

public class StepCounter : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int step = 1;
        string st;
        if (input.Parameters != null && input.Parameters.TryGetValue("step", out st) && st != null)
            step = int.Parse(st, CultureInfo.InvariantCulture);

        double lo = 0.0, hi = 1.0;

        if (step > 1)
        {
            string[] prev;
            try { prev = input.GetPreviousOutputs(); }
            catch (Exception ex) { return Task.FromResult(AgentLayerResult.Error("cannot read parents: " + ex.Message)); }
            if (prev == null || prev.Length == 0)
                return Task.FromResult(AgentLayerResult.Error("missing parent outputs for step " + step));

            long total = 0;
            bool first = true;
            foreach (var p in prev)
            {
                if (p == null) return Task.FromResult(AgentLayerResult.Error("null parent output"));
                var d = JsonSerializer.Deserialize<Payload>(p);
                if (d == null) return Task.FromResult(AgentLayerResult.Error("bad parent output"));
                if (first) { lo = d.lo; hi = d.hi; first = false; }
                total += d.count;
            }
            double pmid = (lo + hi) / 2.0;
            if (total >= Core.K) hi = pmid; else lo = pmid;
        }

        double mid = (lo + hi) / 2.0;
        long c = Core.CountShard(input.WorkerIndex, input.TotalWorkers, mid, ct);

        var res = new Payload { lo = lo, hi = hi, mid = mid, count = c, step = step };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(res)));
    }
}

public class FinalStep : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        string[] prev = input.GetPreviousOutputs();
        if (prev == null || prev.Length == 0)
            return Task.FromResult(AgentLayerResult.Error("missing parent outputs for final step"));

        double lo = 0.0, hi = 1.0;
        long total = 0;
        bool first = true;
        int parents = 0;
        foreach (var p in prev)
        {
            if (p == null) return Task.FromResult(AgentLayerResult.Error("null parent output"));
            var d = JsonSerializer.Deserialize<Payload>(p);
            if (d == null) return Task.FromResult(AgentLayerResult.Error("bad parent output"));
            if (first) { lo = d.lo; hi = d.hi; first = false; }
            total += d.count;
            parents++;
        }

        double mid = (lo + hi) / 2.0;
        if (total >= Core.K) hi = mid; else lo = mid;
        double answer = (lo + hi) / 2.0;

        var res = new
        {
            step = 33,
            parents = parents,
            count = total,
            lo = lo,
            hi = hi,
            answer = answer,
            answer17 = answer.ToString("G17", CultureInfo.InvariantCulture)
        };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(res)));
    }
}

